package model;

/** Represents one row of the 'users' table. */
public class User {

    public static final String ROLE_ADMIN = "ADMIN";
    public static final String ROLE_CUSTOMER = "CUSTOMER";

    private int userId;
    private String fullName;
    private String email;
    private String password;
    private String role;

    public User() {
    }

    /** Used when creating a new user (id is generated by the database). */
    public User(String fullName, String email, String password, String role) {
        this.fullName = fullName;
        this.email = email;
        this.password = password;
        this.role = role;
    }

    public User(int userId, String fullName, String email, String password, String role) {
        this(fullName, email, password, role);
        this.userId = userId;
    }

    public boolean isAdmin() {
        return ROLE_ADMIN.equals(role);
    }

    public int getUserId() { return userId; }
    public void setUserId(int userId) { this.userId = userId; }
    public String getFullName() { return fullName; }
    public void setFullName(String fullName) { this.fullName = fullName; }
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }
    public String getRole() { return role; }
    public void setRole(String role) { this.role = role; }
}
